import {seed,concernOptions,branchOptions} from './data.js';
import {icon,escapeHTML as e} from './icons.js';
import {renderClinician} from './clinician.js';
import {medicationDefaults, medicineRowHTML, medicineLinkHTML, medicationDetailHTML} from './medications.js';
import {automaticRoute, ensureExaminations, examinationSteps, stepsForExam, canFinishExamination, applyTemplateToExam, renderNurse, nursingRecordHTML} from './nurse.js';
const KEY='zvem-workflow-demo-v2';
let state=structuredClone(seed);
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===2&&saved.patients?.ana&&Array.isArray(saved.requests))state=saved;}catch{}
function prepareClinicalState(data){
 data.examinations??=[];data.nurseFilter??='Open';
 for(const p of Object.values(data.patients)){p.medications=p.medications.map(m=>({...medicationDefaults[m.id],...m}));}
 if(!data.clinicalFeatures){
  if(!data.patients.ana.medications.some(m=>m.id==='m4'))data.patients.ana.medications.push(structuredClone(medicationDefaults.m4));
  if(!data.requests.some(r=>r.id==='r4'))data.requests.unshift({id:'r4',patient:'ana',type:'Prescription',title:'Short-course medicine: Ibuprofen',category:'Medical',route:'Doctor',status:'Pending',medications:['m4'],answers:[['Medicine','Ibuprofen 400 mg'],['Planned treatment','17 October 2026 to 21 October 2026'],['Prescription status','Not issued — sample clinical review']],created:'Today · 09:10'});
  data.clinicalFeatures=1;
 }
 delete data.demoAccount;
 ensureExaminations(data);return data;
}
state=prepareClinicalState(state);
try{if(JSON.parse(localStorage.getItem(KEY))?.demoAccount)localStorage.setItem(KEY,JSON.stringify(state));}catch{}
let flow=null,returnFocus=null,expandedPassport=false;
const app=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
const role=()=>location.hash==='#doctor'?'doctor':location.hash==='#nurse'?'nurse':'patient';
const patient=()=>state.patients[state.patient];
const uid=prefix=>prefix+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);
const persist=()=>{prepareClinicalState(state);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}};
const dateLabel=date=>new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
const initials=name=>name.split(' ').map(n=>n[0]).join('');
const pill=(label,tone='')=>`<span class="pill ${tone}">${e(label)}</span>`;
const pendingMeds=person=>state.requests.filter(r=>r.patient===person&&r.type==='Prescription'&&r.status==='Pending').flatMap(r=>r.medications||[]);
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('checkCircle')}<span>${e(message)}</span>`;document.getElementById('toast-region').replaceChildren(el);setTimeout(()=>el.remove(),4200);}
function commit(message){persist();render();if(message)toast(message);}
function activity(message){state.activity.unshift({id:uid('act'),message});}
function render(){const doctor=role()==='doctor',nurse=role()==='nurse';app.innerHTML=`<a href="#main-content" class="skip">Skip to main content</a><div class="prototype-bar"><span>${icon('activity')} Proposed zVEM additions · Interactive demonstration</span><nav class="version-links" aria-label="Demonstration versions"><a href="#patient" data-action="version" data-role="patient" class="${role()==='patient'?'active':''}" ${role()==='patient'?'aria-current="page"':''}>${icon('users')} Patient</a><a href="#doctor" data-action="version" data-role="doctor" class="${doctor?'active':''}" ${doctor?'aria-current="page"':''}>${icon('stethoscope')} Doctor</a><a href="#nurse" data-action="version" data-role="nurse" class="${nurse?'active':''}" ${nurse?'aria-current="page"':''}>${icon('heart')} Nurse</a></nav></div>
 <header class="site-header"><a href="#patient" class="wordmark" data-action="version" data-role="patient"><strong>zVEM</strong><span>Suggested care workflows</span></a>${doctor?'<div class="small muted">Dr. Nina Kovač · Doctor workspace</div>':nurse?'<div class="small muted">Maja Petrič · Nurse workspace</div>':`<button class="account-button" data-action="profile"><span class="avatar">${initials(patient().name)}</span><span>${e(patient().name)}<small>${state.patient==='ana'?'My care':'Authorized family profile · demo'}</small></span>${icon('chevron')}</button>`}</header>
 <main class="page" id="main-content">${doctor?renderClinician(state,{icon,escapeHTML:e,passportHTML,medicineLinkHTML,nursingRecordHTML}):nurse?renderNurse(state,{icon,escapeHTML:e,passportHTML}):patientPage()}<footer class="footer"><span>Fictional records · Local demo · No real bookings, prescriptions or test orders</span><div><button class="btn subtle" data-action="explain">How this demonstration works</button><button class="btn subtle" data-action="reset-confirm">Reset demo</button></div></footer></main>`;}
function passportHTML(person,doctor=false){const p=state.patients[person];return `<section class="panel passport ${doctor?'doctor-passport':''} ${expandedPassport?'expanded':''}" aria-label="Patient Passport for ${e(p.name)}"><div class="passport-title"><div><p class="eyebrow">ONE RECORD FOR EVERY VISIT</p><h2>Patient Passport</h2><p>Already available to your care team.</p></div>${icon('passport')}</div><div class="passport-mobile-summary"><strong>${e(p.name)}</strong><br><span style="color:var(--red)">Allergies: ${e(p.allergies.join(', '))}</span><br>${p.medications.length} medications · ${p.operations.length} previous operation</div><div class="passport-content"><div class="identity"><span class="avatar">${initials(p.name)}</span><div><h3>${e(p.name)}</h3><p>Born ${e(p.dob)}</p><p>${e(p.insurance)}</p></div></div><div class="allergy">${icon('alert')}<div><strong>Allergies</strong>${e(p.allergies.join(', '))}</div></div><div class="record-group"><h3>${icon('pill')} Medications & treatment dates</h3>${p.medications.map(m=>medicineRowHTML(m,person,{icon,escapeHTML:e},doctor)).join('')}</div><div class="record-group"><h3>${icon('activity')} Ongoing conditions</h3>${p.conditions.map(c=>`<div class="record-item">${e(c)}</div>`).join('')}</div><div class="record-group"><h3>${icon('stethoscope')} Previous operations</h3>${p.operations.map(o=>`<div class="record-item"><strong>${e(o.name)}</strong><span>${e(o.date)}</span></div>`).join('')}</div><div class="record-group"><h3>${icon('shield')} Medication interactions</h3><p class="small muted">${doctor?'Select a medicine above to see interaction examples, precautions and its treatment timeline.':'Your care team can open each medicine to review interaction examples and precautions.'} Full clinical interaction screening is not connected.</p></div><div class="record-group"><h3>${icon('users')} Personal doctor</h3><p class="record-item">${e(p.doctor)}</p><span class="small muted">Health Centre Ljubljana</span></div></div><div class="passport-note">Sample clinical record. Existing medication, allergy and procedure data is attached to each request automatically.</div>${!doctor?`<button class="btn passport-toggle" data-action="toggle-passport" aria-expanded="${expandedPassport}">${expandedPassport?'Close passport details':'View medications, allergies & history'} ${icon('chevron')}</button>`:''}</section>`;}
function patientPage(){const p=patient();const requests=state.requests.filter(r=>r.patient===state.patient);const offers=state.offers.filter(o=>o.patient===state.patient&&o.status==='Offered');return `<div class="intro"><div><p class="eyebrow">PATIENT VERSION</p><h1>Hello, ${e(p.name.split(' ')[0])}. What do you need?</h1><p>Choose a box. We’ll guide you through the rest.</p></div><span class="step-label">${icon('checkCircle')} Simple guided answers</span></div><div class="patient-layout"><div class="stack"><section class="question-hero"><span class="tree-symbol">${icon('activity')}</span><p class="eyebrow">GUIDED QUESTIONS · DECISION TREE</p><h2>I need help with my health.</h2><p>Answer simple questions, one at a time. Your answers go to the care team with your Patient Passport.</p><button class="btn primary" data-action="start" data-kind="symptoms">Start the guided questions ${icon('arrow')}</button><div class="process-preview"><span><b>1</b> Choose answers</span>${icon('arrow')}<span><b>2</b> Automatic routing</span>${icon('arrow')}<span><b>3</b> Professional review</span></div></section>
 <div class="action-grid"><button class="action-tile" data-action="start" data-kind="tests">${icon('activity')}<strong>Blood or urine test</strong><span>Choose a test and request it</span></button><button class="action-tile" data-action="start" data-kind="prescription">${icon('pill')}<strong>Repeat medication</strong><span>Select your existing medicine</span></button><button class="action-tile" data-action="start" data-kind="admin">${icon('file')}<strong>Administrative request</strong><span>Choose the document you need</span></button></div>
 ${offers.map(o=>`<section class="panel offer"><p class="eyebrow">AN EARLIER APPOINTMENT IS AVAILABLE</p><h3>${dateLabel(o.date)} · ${e(o.time)}</h3><p>A cancelled appointment has been offered to you. Your current booking stays in place until you accept.</p><div class="route-control"><button class="btn primary" data-action="accept-offer" data-id="${e(o.id)}">Accept this time ${icon('check')}</button><button class="btn" data-action="decline-offer" data-id="${e(o.id)}">Keep my current time</button></div></section>`).join('')}
 ${appointmentsPanel()}<section class="panel"><div class="panel-head"><div><h2>Your requests</h2><p>The next step appears here after your team reviews it.</p></div>${icon('inbox')}</div>${requests.length?requests.map(requestStatus).join(''):'<p class="empty">You have no requests yet.</p>'}</section>
 <button class="btn" data-action="start" data-kind="checkin">${icon('users')} At the clinic without an appointment? Check in</button>
 </div><aside class="stack passport-column">${passportHTML(state.patient)}</aside></div>`;}
function appointmentsPanel(){const booked=state.appointments.filter(a=>a.patient===state.patient&&a.status==='Booked').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const available=getSlots('Consultation').slice(0,3);const wait=state.waitingList.find(w=>w.patient===state.patient);return `<section class="panel" id="appointments"><div class="panel-head"><div><h2>Your upcoming appointments</h2><p>Can’t come? Cancel here without calling.</p></div>${icon('calendar')}</div><div class="appointment-list">${booked.map(a=>`<article class="appointment"><div class="date-block"><span>OCT</span><strong>${a.date.slice(-2)}</strong></div><div class="appointment-info"><h3>${e(a.title)}</h3><p class="time">${icon('clock')} ${dateLabel(a.date)} · ${e(a.time)}</p><p>${e(a.place)}</p></div><button class="btn danger" data-action="cancel" data-id="${e(a.id)}">Cancel</button></article>`).join('')||'<p class="empty">No upcoming appointments. Choose an available time below.</p>'}</div><h3 class="section-label">Available doctor appointments</h3><div class="slots">${available.map(slotButton).join('')||'<p class="empty">No sample times available.</p>'}</div><button class="toggle-choice ${wait?.enabled?'selected':''}" role="checkbox" aria-checked="${!!wait?.enabled}" data-action="waiting-list"><span class="choice-box">${wait?.enabled?icon('check'):''}</span><span>Offer me an earlier suitable appointment</span></button><div class="plan-reminder">${icon('bell')} Appointment reminders and regular follow-ups are shown here. Reminder delivery is simulated.</div></section>`;}
function slotButton(s){return `<button class="slot" data-action="book-slot" data-id="${e(s.id)}"><span>${dateLabel(s.date)}</span><strong>${e(s.time)}</strong><span>Choose this time</span></button>`;}
function requestStatus(r){return `<article class="request-status"><div class="status-top"><h3>${e(r.title)}</h3>${pill(r.status,r.status==='Pending'?'amber':'')}</div><p>${r.status==='Pending'?`Sent to ${e(r.route.toLowerCase())} review. Your Passport is attached.`:e(r.response||'Updated by your care team.')}</p>${r.status==='Approved'&&r.type==='Tests'&&r.collection==='Laboratory'&&!r.booked?`<button class="btn" data-action="lab-times" data-id="${e(r.id)}">${icon('calendar')} Choose a laboratory time</button>`:''}${r.status==='Appointment needed'&&!r.booked?`<button class="btn" data-action="consultation-times" data-id="${e(r.id)}">${icon('calendar')} Choose ${r.route==='Nurse'?'a nurse':'a doctor'} appointment</button>`:''}${r.type==='Symptoms'?`<button class="btn subtle" data-action="view-answers" data-id="${e(r.id)}">View my selected answers ${icon('chevron')}</button>`:''}</article>`;}
function getSlots(kind){const slots=[...state.slots];for(const a of state.appointments.filter(a=>a.status==='Cancelled'&&a.kind===kind)){if(!slots.some(s=>s.kind===kind&&s.date===a.date&&s.time===a.time))slots.push({id:'released-'+a.id,date:a.date,time:a.time,kind});}return slots.filter((s,i,all)=>all.findIndex(t=>t.kind===s.kind&&t.date===s.date&&t.time===s.time)===i).filter(s=>s.kind===kind&&!state.appointments.some(a=>a.status==='Booked'&&a.date===s.date&&a.time===s.time&&a.kind===kind)&&!state.offers.some(o=>o.status==='Offered'&&o.date===s.date&&o.time===s.time&&o.kind===kind)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));}
function offerReleased(slot,excluded,declined=[]){if(slot.kind!=='Consultation')return;const next=state.waitingList.find(w=>w.enabled&&w.patient!==excluded&&!declined.includes(w.patient)&&state.appointments.some(a=>a.id===w.appointment&&a.status==='Booked'&&a.date+a.time>slot.date+slot.time)&&!state.offers.some(o=>o.patient===w.patient&&o.status==='Offered'));if(next){state.offers.push({id:uid('offer'),patient:next.patient,appointment:next.appointment,date:slot.date,time:slot.time,kind:slot.kind,status:'Offered',excluded,declined});activity(`${dateLabel(slot.date)} at ${slot.time} automatically offered to ${state.patients[next.patient].name}, the next eligible demo patient.`);}else activity(`${dateLabel(slot.date)} at ${slot.time} released to available appointments.`);}
function showModal(title,body,footer='',subtitle=''){if(!modalRoot.children.length)returnFocus=document.activeElement;document.getElementById('toast-region').replaceChildren();app.inert=true;modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><div><h2 id="dialog-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog">${icon('x')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';modalRoot.querySelector('.choice,.btn,.close')?.focus();}
function closeModal(){modalRoot.innerHTML='';app.inert=false;document.body.style.overflow='';flow=null;if(returnFocus?.isConnected)returnFocus.focus();}
function choice(value,label,description='',selected=false,multiple=false){return `<button class="choice ${selected?'selected':''}" role="${multiple?'checkbox':'radio'}" aria-checked="${selected}" data-action="choose" data-value="${e(value)}"><span class="choice-box">${selected?icon('check'):''}</span><span><strong>${e(label)}</strong>${description?`<small>${e(description)}</small>`:''}</span></button>`;}
function choices(options,selected,multiple=false){return `<div class="choice-grid" role="${multiple?'group':'radiogroup'}" aria-label="Choose ${multiple?'one or more answers':'one answer'}">${options.map(o=>{const [value,label,desc]=Array.isArray(o)?o:[o,o,''];return choice(value,label,desc||'',multiple?(selected||[]).includes(value):selected===value,multiple);}).join('')}</div>`;}
// Anatomical left/right refer to the patient, not the viewer.
const bodyRegions = [
 ['Head','M90 35 a30 30 0 1 0 60 0 a30 30 0 1 0 -60 0'],
 ['Neck','M106 66 H134 V90 H106 Z'],
 ['Chest','M85 92 Q120 82 155 92 L150 158 H90 Z','Upper back'],
 ['Abdomen','M90 162 H150 L155 214 H85 Z','Lower back'],
 ['Pelvis','M85 218 H155 L158 251 L120 265 L82 251 Z','Buttocks'],
 ['Right arm','M80 94 L85 153 L65 217 L45 210 L58 135 Q63 104 80 94'],
 ['Left arm','M160 94 L155 153 L175 217 L195 210 L182 135 Q177 104 160 94'],
 ['Right hand','M44 214 L64 221 L57 253 Q40 269 34 249 Z'],
 ['Left hand','M196 214 L176 221 L183 253 Q200 269 206 249 Z'],
 ['Right leg','M83 257 L117 270 L113 352 L105 425 H81 L78 350 Z'],
 ['Left leg','M157 257 L123 270 L127 352 L135 425 H159 L162 350 Z'],
 ['Right foot','M81 429 H105 L106 450 Q87 462 68 453 Z'],
 ['Left foot','M135 429 H159 L172 453 Q153 462 134 450 Z']
];
function painMap(selected=[]){return `<p class="question-hint">Click or tap where it hurts. Select more than one area if needed; select again to remove. Left and right refer to your body.</p><div class="body-maps">${['Front','Back'].map(view=>`<figure><figcaption>${view}</figcaption><svg viewBox="20 0 200 470" role="group" aria-label="${view} of body: select pain locations">${bodyRegions.map(([name,path,back])=>{const label=view==='Back'?(back||name.replace('Right','TEMP').replace('Left','Right').replace('TEMP','Left')):name;const value=`${label} (${view.toLowerCase()})`;return `<path d="${path}" class="body-region ${selected.includes(value)?'selected':''}" role="button" tabindex="0" aria-label="${value}" aria-pressed="${selected.includes(value)}" data-action="choose" data-value="${value}"><title>${value}</title></path>`;}).join('')}</svg></figure>`).join('')}</div><p class="pain-selection" aria-live="polite"><strong>Selected:</strong> ${selected.length?e(selected.join('; ')):'No areas selected yet'}</p>${choices(['Other','All over','I’m not sure'],selected,true)}`;}
function otherSymptomField(a){return a.detail?.includes('Other')?`<div class="other-symptom"><label for="other-symptom">Describe your other symptoms <span>(optional)</span></label><textarea id="other-symptom" rows="3" maxlength="1000" placeholder="Tell your care team what you are experiencing…">${e(a.otherSymptom||'')}</textarea></div>`:'';}
function steps(){if(flow.kind==='symptoms'){if(flow.answers.urgency&&flow.answers.urgency!=='No')return ['urgency','summary'];return ['urgency','concern',...(flow.answers.concern&&flow.answers.concern!=='unsure'?['detail']:[]),'duration','summary'];}return {tests:['test','collection','summary'],prescription:['medication','summary'],admin:['admin','summary'],checkin:['checkin','summary']}[flow.kind];}
function currentStep(){return steps()[Math.min(flow.index,steps().length-1)];}
function canContinue(){const key=currentStep();if(key==='summary')return true;const val=flow.answers[key];return Array.isArray(val)?val.length>0:!!val;}
function flowRoute(){if(flow.kind!=='symptoms')return flow.kind==='admin'?'Administration':'Doctor';if(flow.answers.urgency!=='No')return 'Doctor';return ['cold','urine'].includes(flow.answers.concern)?'Nurse':'Doctor';}
function flowCategory(){return flow.kind==='admin'?'Administrative':flow.kind==='symptoms'&&flow.answers.urgency!=='No'?'Urgent':'Medical';}
function flowPairs(){const a=flow.answers;if(flow.kind==='symptoms')return [['Urgent help needed?',a.urgency],...(a.concern?[['Main concern',concernOptions.find(c=>c.value===a.concern)?.label||a.concern]]:[]),...(a.detail?.length?[['Selected answers',a.detail.join('; ')]]:[]),...(a.detail?.includes('Other')&&a.otherSymptom?.trim()?[['Other symptoms',a.otherSymptom.trim()]]:[]),...(a.duration?[['Duration',a.duration]]:[])];if(flow.kind==='tests')return [['Tests',a.test.join(' + ')],['Collection',a.collection],['Patient',state.patients[flow.patient].name]];if(flow.kind==='prescription')return [['Medication',state.patients[flow.patient].medications.filter(m=>a.medication.includes(m.id)).map(m=>m.name+' '+m.dose).join('; ')],['Details','Existing medication and allergy record attached']];return [[flow.kind==='admin'?'Document':'Reason for visit',a[flow.kind==='admin'?'admin':'checkin']]];}
function answersHTML(pairs){return `<div class="answer-list">${pairs.map(([q,a])=>`<div class="answer-row"><span>${e(q)}</span><strong>${e(a)}</strong></div>`).join('')}</div>`;}
function drawFlow(){const step=currentStep(),a=flow.answers;let title='',body='';const progress=`<div class="progress" aria-label="Step ${flow.index+1} of ${steps().length}">${steps().map((_,i)=>`<span class="${i<=flow.index?'done':''}"></span>`).join('')}</div>`;
 if(step==='urgency'){title='Do you feel you need urgent help?';body=`<p class="question-hint">Choose one box. If you think this is an emergency, seek emergency help directly.</p>${choices([['Yes','Yes, I need urgent help'],['No','No, this is not urgent'],['Not sure','I’m not sure']],a.urgency)}`;}
 if(step==='concern'){title='What would you like help with?';body=`<p class="question-hint">Choose the closest match, or select Other symptoms.</p>${choices(concernOptions.map(c=>[c.value,c.label]),a.concern)}`;}
 if(step==='detail'){const branch=branchOptions[a.concern];title=a.concern==='pain'?'Where does it hurt?':branch.question;body=(a.concern==='pain'?painMap(a.detail):`<p class="question-hint">Choose all the symptoms that apply.</p>${choices([...new Set([...branch.choices,'Other'])],a.detail,true)}`)+otherSymptomField(a);}
 if(step==='duration'){title='How long has this been happening?';body=choices(['Today','A few days','A week or longer','I’m not sure / not applicable'],a.duration);}
 if(step==='test'){title='Which test do you need?';body=`<p class="question-hint">Choose one or both. Your doctor will review the request before ordering.</p>${choices([['Blood test','Blood test','Request a blood test for professional review'],['Urine test','Urine test','Request a urine test for professional review']],a.test,true)}`;}
 if(step==='collection'){title='Where would you prefer collection?';body=`<p class="question-hint">Home collection depends on the test and your provider’s approval.</p>${choices([['Laboratory','At the laboratory','Choose an available time after approval'],['Home kit','Request home collection','Ask about a urine container or suitable home blood kit']],a.collection)}`;}
 if(step==='medication'){title='Which medication do you need?';const meds=state.patients[flow.patient].medications;const blocked=pendingMeds(flow.patient);body=`<p class="question-hint">Select your existing medication. Your care team already has the details.</p><div class="choice-grid" role="group" aria-label="Medication choices">${meds.map(m=>blocked.includes(m.id)?`<div class="notice">${icon('clock')}<span><strong>${e(m.name)}</strong><br>A renewal request is already awaiting review.</span></div>`:choice(m.id,m.name+' · '+m.dose,m.when,(a.medication||[]).includes(m.id),true)).join('')}</div>`;}
 if(step==='admin'){title='Which document do you need?';body=`<p class="question-hint">Choose a box. Your details will be filled in automatically.</p>${choices(['Attendance confirmation','Copy of a medical report','Sick-leave certificate request'],a.admin)}`;}
 if(step==='checkin'){title='What brings you to the clinic?';body=`<div class="notice">${icon('passport')}<span>Sample insurance card recognized: <strong>${e(state.patients[flow.patient].name)}</strong></span></div>${choices(['A health concern','A regular follow-up','An administrative request'],a.checkin)}`;}
 if(step==='summary'){title=flow.kind==='checkin'?'Confirm your check-in':'Check your choices';body=answersHTML(flowPairs());if(flow.kind==='symptoms'){const urgent=flowCategory()==='Urgent';body=`${urgent?`<div class="notice urgent">${icon('alert')}<span><strong>Do not wait for a reply here if you need urgent help.</strong><br>Contact your healthcare team directly. If you think this is an emergency, seek emergency care now. This demo cannot assess urgency or contact anyone.</span></div>`:''}${body}<div class="decision-preview"><h3>Where your answers go</h3><div class="tree-path"><span class="tree-node">Your answers</span>${icon('arrow')}<span class="tree-node">${urgent?'Urgent flag':'Auto → '+flowRoute()}</span>${icon('arrow')}<span class="tree-node">Professional decision</span></div><p>Demo rules send your request to the appropriate queue automatically. The receiving professional reviews the request. This sample tree does not diagnose or give treatment advice.</p></div>`;}else body+=`<div class="order-summary">${icon('passport')} Your Patient Passport is attached automatically.</div>`;}
 const subject={symptoms:'Guided questions',tests:'Blood & urine test request',prescription:'Repeat prescription',admin:'Administrative request',checkin:'Clinic check-in'}[flow.kind];showModal(subject,`${progress}<h3 class="question-title">${title}</h3>${body}${flow.kind==='symptoms'?'<p class="warning-note">Illustrative decision tree · Not clinically validated · Demo only</p>':''}`,`<button class="btn" data-action="flow-back">${flow.index?'Back':'Cancel'}</button><button class="btn primary" data-action="flow-next" ${!canContinue()?'disabled':''}>${step==='summary'?(flow.kind==='checkin'?'Confirm check-in':'Send request'):'Continue'} ${icon(step==='summary'?'check':'arrow')}</button>`,`Step ${flow.index+1} of ${steps().length} · ${state.patients[flow.patient].name}`);
}
function submitFlow(){const a=flow.answers;const person=flow.patient;const type={symptoms:'Symptoms',tests:'Tests',prescription:'Prescription',admin:'Administrative',checkin:'Walk-in'}[flow.kind];if(flow.kind==='prescription'&&a.medication.some(id=>pendingMeds(person).includes(id))){flow.index=0;drawFlow();toast('A selected medication already has a pending request.');return;}if(flow.kind==='tests'&&state.requests.some(r=>r.patient===person&&r.type==='Tests'&&r.status==='Pending'&&r.tests.slice().sort().join()===a.test.slice().sort().join())){closeModal();toast('That test request is already awaiting review.');return;}
 let title=flow.kind==='symptoms'?(concernOptions.find(c=>c.value===a.concern)?.label||'Request for urgent help'):flow.kind==='tests'?a.test.join(' + '):flow.kind==='prescription'?'Repeat prescription: '+state.patients[person].medications.filter(m=>a.medication.includes(m.id)).map(m=>m.name).join(', '):flow.kind==='admin'?a.admin:'Walk-in: '+a.checkin;
 const clinicalAdmin=flow.kind==='admin'&&a.admin==='Sick-leave certificate request';
 const r={id:uid('r'),patient:person,type,title,category:clinicalAdmin?'Medical':flow.kind==='checkin'&&a.checkin==='An administrative request'?'Administrative':flowCategory(),route:clinicalAdmin?'Doctor':flow.kind==='checkin'?(a.checkin==='An administrative request'?'Administration':'Nurse'):flowRoute(),status:'Pending',answers:flowPairs(),created:'Just now',...(flow.kind==='tests'?{tests:a.test,collection:a.collection}:{}),...(flow.kind==='prescription'?{medications:a.medication}:{})};state.requests.unshift(r);state.selectedRequest=r.id;state.filter='Pending';const kind=flow.kind;closeModal();commit();if(kind==='checkin'){state.ticket++;persist();showModal('You are checked in.',`<div class="checkin-ticket"><span>YOUR DEMO QUEUE NUMBER</span><strong>A–${String(state.ticket).padStart(3,'0')}</strong><p>Example wait: 20–30 minutes</p><p class="small muted">Collect your buzzer at reception.<br>Tell reception if you need urgent help.</p></div><p class="warning-note">Sample ticket and estimate. No real card reader, buzzer or queue is connected.</p>`,`<span></span><button class="btn primary" data-action="close">Done</button>`);}else showModal('Your request is ready for review.',`<div class="success"><div class="success-mark">${icon('check')}</div><h3>${e(title)}</h3><p>Your choices and Patient Passport are together in the ${e(r.route.toLowerCase())} queue.</p><div class="notice">${icon('inbox')}<span>Watch “Your requests” for the next step. This demonstration does not contact a real healthcare provider.</span></div></div>`,`<button class="btn" data-action="close">Back to my care</button><button class="btn primary" data-action="version" data-role="${r.route==='Doctor'?'doctor':'nurse'}">See ${r.route==='Doctor'?'doctor':'nurse'} version ${icon('arrow')}</button>`);}
function openBooking(slotId,orderId=null){const request=orderId?state.requests.find(r=>r.id===orderId):null;const kind=request?.type==='Tests'&&request.status==='Approved'?'Laboratory':request?.route==='Nurse'?'Nurse':'Consultation';const slot=getSlots(kind).find(s=>s.id===slotId);if(!slot){toast('This time is no longer available. Choose another.');return;}showModal('Book this appointment?',`<div class="order-summary"><h3>${dateLabel(slot.date)} · ${e(slot.time)}</h3><p>${kind==='Laboratory'?'Blood / urine sample collection':kind==='Nurse'?'Nurse consultation':'Doctor consultation'}</p><p>${e(patient().name)} · Health Centre Ljubljana</p></div><p class="small muted" style="margin-top:20px">This books the sample calendar only.</p>`,`<button class="btn" data-action="close">Back</button><button class="btn primary" data-action="confirm-book" data-id="${e(slot.id)}" data-order="${e(orderId||'')}">Confirm appointment ${icon('check')}</button>`);}
function reviewModal(id,outcome){const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='Pending'||r.route!=='Doctor')return;const label=outcome==='tests'?'Approve test request':outcome==='prescription'?'Review and issue demo prescription':outcome==='contact'?'Record urgent contact required':'Arrange a consultation';showModal(label,`<p><strong>${e(state.patients[r.patient].name)}</strong> · ${e(r.title)}</p>${answersHTML(r.answers)}<div class="notice" style="margin-top:20px">${icon('shield')}<span>Confirm that you have reviewed the attached Patient Passport. This action updates demo records only; no clinical order is issued.</span></div>`,`<button class="btn" data-action="close">Back</button><button class="btn primary" data-action="confirm-review" data-id="${e(id)}" data-outcome="${e(outcome)}">${outcome==='prescription'?'Reviewed · issue in demo':'Reviewed · confirm'} ${icon('check')}</button>`);}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
 switch(action){
 case'version':closeModal();location.hash=el.dataset.role;render();window.scrollTo(0,0);break;
 case'close':closeModal();break;
 case'start':flow={kind:el.dataset.kind,index:0,patient:state.patient,answers:{}};drawFlow();break;
 case'choose':{if(!flow)return;const key=currentStep();const multi=['detail','test','medication'].includes(key);if(multi){let values=flow.answers[key]||[];values=values.includes(value)?values.filter(v=>v!==value):[...values,value];if(value.includes('sure')&&values.includes(value))values=[value];else values=values.filter(v=>!v.includes('sure'));flow.answers[key]=values;}else{if(key==='concern'&&value!==flow.answers.concern){delete flow.answers.detail;delete flow.answers.otherSymptom;delete flow.answers.duration;}if(key==='urgency'&&value!==flow.answers.urgency){delete flow.answers.concern;delete flow.answers.detail;delete flow.answers.otherSymptom;delete flow.answers.duration;}flow.answers[key]=value;if(key==='concern'&&value==='other')flow.answers.detail=['Other'];}const scroll=modalRoot.querySelector('.modal-body').scrollTop;drawFlow();modalRoot.querySelector('.modal-body').scrollTop=scroll;[...modalRoot.querySelectorAll('[data-action="choose"]')].find(b=>b.dataset.value===value)?.focus({preventScroll:true});break;}
 case'flow-back':if(!flow)return;if(flow.index===0)closeModal();else{flow.index--;drawFlow();}break;
 case'flow-next':if(!flow||!canContinue())return;if(currentStep()==='summary')submitFlow();else{flow.index++;drawFlow();}break;
 case'toggle-passport':expandedPassport=!expandedPassport;render();document.querySelector('.passport-toggle')?.focus({preventScroll:true});break;
 case'profile':showModal('Whose care are you managing?',`<div class="choice-grid"><button class="choice" data-action="profile-select" data-value="ana"><span class="choice-box">${state.patient==='ana'?icon('check'):''}</span><span><strong>Ana Novak</strong><small>My own care</small></span></button><button class="choice" data-action="profile-select" data-value="marija"><span class="choice-box">${state.patient==='marija'?icon('check'):''}</span><span><strong>Marija Novak</strong><small>Family member · Authorized demo access</small></span></button></div><p class="warning-note">Fictional profiles. A live service must verify the patient’s authorization.</p>`);break;
 case'profile-select':state.patient=value;expandedPassport=false;closeModal();commit();window.scrollTo(0,0);break;
 case'book-slot':openBooking(id,el.dataset.order||null);break;
 case'confirm-book':{const orderId=el.dataset.order||null;const order=orderId?state.requests.find(r=>r.id===orderId&&r.patient===state.patient&&!r.booked&&((r.status==='Approved'&&r.type==='Tests'&&r.collection==='Laboratory')||r.status==='Appointment needed')):null;if(orderId&&!order){closeModal();toast('This test request is not ready for booking.');break;}const kind=order?.type==='Tests'&&order.status==='Approved'?'Laboratory':order?.route==='Nurse'?'Nurse':'Consultation';const slot=getSlots(kind).find(s=>s.id===id);if(!slot){closeModal();commit('That time was just taken. Please choose another.');break;}const appointment={id:uid('a'),patient:state.patient,date:slot.date,time:slot.time,kind,title:kind==='Laboratory'?order.tests.join(' + '):kind==='Nurse'?'Nurse consultation':'Doctor consultation',place:'Health Centre Ljubljana · '+(kind==='Laboratory'?'Laboratory':kind==='Nurse'?'Nurse clinic':'Room 12'),status:'Booked',...(order?{orderId}:{} )};state.appointments.push(appointment);if(order)order.booked=true;const wait=state.waitingList.find(w=>w.patient===state.patient);if(wait&&kind==='Consultation'&&!state.appointments.some(a=>a.id===wait.appointment&&a.status==='Booked'))wait.appointment=appointment.id;activity(`${patient().name} booked ${dateLabel(slot.date)} at ${slot.time}.`);closeModal();commit('Appointment booked. It is now in your upcoming appointments.');break;}
 case'cancel':{const a=state.appointments.find(a=>a.id===id&&a.patient===state.patient&&a.status==='Booked');if(!a)break;showModal('Cancel this appointment?',`<div class="order-summary"><h3>${e(a.title)}</h3><p>${dateLabel(a.date)} · ${e(a.time)}</p><p>${e(a.place)}</p></div><div class="notice" style="margin-top:20px">${icon('users')}<span>A suitable released doctor appointment is automatically offered to the next eligible demo patient.</span></div>`,`<button class="btn" data-action="close">Keep appointment</button><button class="btn danger" data-action="confirm-cancel" data-id="${e(id)}">Yes, cancel</button>`);break;}
 case'confirm-cancel':{const a=state.appointments.find(a=>a.id===id&&a.patient===state.patient&&a.status==='Booked');if(!a){closeModal();break;}a.status='Cancelled';if(a.orderId){const order=state.requests.find(r=>r.id===a.orderId);if(order)order.booked=false;}activity(`${patient().name} cancelled ${dateLabel(a.date)} at ${a.time}.`);offerReleased(a,a.patient);closeModal();commit('Appointment cancelled. The time has been released.');break;}
 case'waiting-list':{let w=state.waitingList.find(w=>w.patient===state.patient);if(!w){const a=state.appointments.find(a=>a.patient===state.patient&&a.status==='Booked'&&a.kind==='Consultation');w={patient:state.patient,appointment:a?.id,enabled:false};state.waitingList.push(w);}w.enabled=!w.enabled;if(!w.enabled){for(const o of state.offers.filter(o=>o.patient===state.patient&&o.status==='Offered')){o.status='Declined';offerReleased(o,o.excluded,[...(o.declined||[]),o.patient]);}}commit(w.enabled?'Earlier appointment offers enabled.':'Earlier appointment offers turned off.');break;}
 case'accept-offer':{const o=state.offers.find(o=>o.id===id&&o.patient===state.patient&&o.status==='Offered');if(!o)break;const a=state.appointments.find(a=>a.id===o.appointment&&a.status==='Booked');if(!a||state.appointments.some(a=>a.status==='Booked'&&a.date===o.date&&a.time===o.time&&a.kind===o.kind)){o.status='Expired';commit('This offer is no longer available. Your current appointments are unchanged.');break;}const old={...a};a.date=o.date;a.time=o.time;o.status='Accepted';state.slots.push({id:uid('s'),date:old.date,time:old.time,kind:old.kind});offerReleased(old,state.patient);activity(`${patient().name} accepted the earlier appointment on ${dateLabel(o.date)} at ${o.time}.`);commit('Earlier appointment confirmed. Your old time has been released.');break;}
 case'decline-offer':{const o=state.offers.find(o=>o.id===id&&o.patient===state.patient&&o.status==='Offered');if(!o)break;o.status='Declined';offerReleased(o,o.excluded,[...(o.declined||[]),o.patient]);commit('Your original appointment is unchanged.');break;}
 case'consultation-times':{const r=state.requests.find(r=>r.id===id&&r.patient===state.patient&&r.status==='Appointment needed'&&!r.booked);if(!r)break;const kind=r.route==='Nurse'?'Nurse':'Consultation';showModal(kind==='Nurse'?'Available nurse appointments':'Available doctor appointments',`<p>${e(r.title)} · Professional review completed</p><div class="slots">${getSlots(kind).map(s=>slotButton(s).replace('data-action="book-slot"',`data-action="book-slot" data-order="${e(r.id)}"`)).join('')||'<p class="empty">No sample appointments are available.</p>'}</div>`);break;}
 case'show-times':document.getElementById('appointments')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case'lab-times':{const r=state.requests.find(r=>r.id===id&&r.patient===state.patient&&r.type==='Tests'&&r.status==='Approved'&&!r.booked&&r.collection==='Laboratory');if(!r)break;showModal('Available laboratory times',`<p>${e(r.tests.join(' + '))} · Approved in this demo</p><div class="slots">${getSlots('Laboratory').map(s=>slotButton(s).replace('data-action="book-slot"',`data-action="book-slot" data-order="${e(r.id)}"`)).join('')||'<p class="empty">No sample laboratory slots are available.</p>'}</div>`);break;}
 case'view-answers':{const r=state.requests.find(r=>r.id===id);if(r)showModal('Your selected answers',answersHTML(r.answers),`<span></span><button class="btn primary" data-action="close">Done</button>`);break;}
 case'filter':if(role()!=='doctor')break;state.filter=value;commit();break;
 case'select-request':if(role()!=='doctor')break;state.selectedRequest=id;commit();if(innerWidth<=760)document.getElementById('request-detail')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case'complete-admin':{if(role()!=='nurse')break;const r=state.requests.find(r=>r.id===id&&r.category==='Administrative'&&r.status==='Pending');if(!r)break;r.status='Completed';r.response='Your administrative request has been completed in this demonstration.';commit('Completed. The patient’s request status has been updated.');break;}
 case'review':if(role()==='doctor')reviewModal(id,el.dataset.outcome);break;
 case'confirm-review':{if(role()!=='doctor')break;const r=state.requests.find(r=>r.id===id&&r.status==='Pending'&&r.route==='Doctor');if(!r){closeModal();break;}const outcome=el.dataset.outcome;if(outcome==='tests'){r.status='Approved';r.response=r.collection==='Laboratory'?'Your blood / urine test request is approved in the demo. Choose a laboratory time below.':'Home collection approved in the demo. Your team would arrange the appropriate kit and collection instructions. Nothing is shipped by this prototype.';}else if(outcome==='prescription'){r.status='Issued in demo';r.response='The prescription is marked issued in the demonstration. No real prescription has been issued.';for(const m of state.patients[r.patient].medications.filter(m=>(r.medications||[]).includes(m.id))){m.issueStatus='Issued';m.issuedAt=new Date().toISOString();}}else if(outcome==='contact'){r.status='Contact required';r.response='Please contact your healthcare team directly. This demo does not arrange urgent care. If you think this is an emergency, seek emergency help now.';}else{r.status='Appointment needed';r.response=`Your ${r.route.toLowerCase()} has requested a consultation in this demo. Choose an available appointment below.`;}closeModal();commit('Review recorded. The next step is now visible to the patient.');break;}
 case'medicine':{if(!['doctor','nurse'].includes(role()))break;const p=state.patients[el.dataset.patient];const m=p?.medications.find(m=>m.id===id);if(!m)break;showModal(m.name+' · '+m.dose,medicationDetailHTML(m,p,{icon,escapeHTML:e}),`<span></span><button class="btn primary" data-action="close">Done</button>`,'Medicine specifications, treatment dates and interactions');break;}
 case'nurse-filter':if(role()!=='nurse')break;state.nurseFilter=value;delete state.nurseTemplateDraft;commit();break;
 case'select-exam':if(role()!=='nurse')break;state.selectedExam=id;delete state.nurseTemplateDraft;commit();if(innerWidth<=760)document.getElementById('request-detail')?.scrollIntoView({behavior:'smooth'});break;
 case'apply-nurse-template':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress'),template=state.nurseTemplates.find(t=>t.id===el.dataset.template);if(!exam||!template)break;applyTemplateToExam(exam,template);state.selectedExam=id;delete state.nurseTemplateDraft;commit(template.name+' checklist applied. No steps were marked complete.');break;}
 case'edit-nurse-template':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress'),template=state.nurseTemplates.find(t=>t.id===exam?.templateId);if(!template)break;state.nurseTemplateDraft={id:template.id,steps:[...template.steps]};commit();break;}
 case'toggle-nurse-template-step':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress'),draft=state.nurseTemplateDraft,step=examinationSteps.find(s=>s.id===el.dataset.step);if(!exam||!draft||draft.id!==exam.templateId||!step||step.required||(draft.id==='samples'&&step.id==='sample'))break;draft.steps=draft.steps.includes(step.id)?draft.steps.filter(s=>s!==step.id):[...draft.steps,step.id];commit();break;}
 case'save-nurse-template':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress'),draft=state.nurseTemplateDraft,template=state.nurseTemplates.find(t=>t.id===draft?.id);if(!exam||!template||template.id!==exam.templateId)break;template.steps=[...draft.steps];applyTemplateToExam(exam,template);delete state.nurseTemplateDraft;commit(template.name+' saved for future visits and applied to this examination.');break;}
 case'cancel-nurse-template':if(role()!=='nurse')break;delete state.nurseTemplateDraft;commit();break;
 case'exam-step':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress');const step=examinationSteps.find(s=>s.id===el.dataset.step);if(!exam||!step||!stepsForExam(exam).some(s=>s.id===step.id)||!['Done','Not applicable','clear'].includes(value)||((step.required||(exam.appointmentId&&step.id==='sample'))&&value==='Not applicable'))break;const entry={value,at:new Date().toISOString(),by:'Nurse Maja Petrič'};if(value==='clear')delete exam.steps[step.id];else exam.steps[step.id]=entry;exam.history.push({step:step.id,...entry});commit('Examination step saved and shared with the doctor.');document.querySelector(`[data-action="exam-step"][data-id="${CSS.escape(id)}"][data-step="${step.id}"]`)?.focus({preventScroll:true});break;}
 case'finish-exam':{if(role()!=='nurse')break;const exam=state.examinations.find(x=>x.id===id&&x.status==='In progress');if(!exam||!canFinishExamination(exam))break;exam.status='Completed';exam.completedAt=new Date().toISOString();const r=state.requests.find(r=>r.id===exam.requestId);if(r&&exam.appointmentId){r.status='Collected in demo';r.response='The nurse recorded sample collection in the demonstration. No real sample was collected.';}else if(r&&r.route==='Nurse'){r.status='Completed';r.response='The nurse completed the examination checklist in the demonstration. The record is shared with your doctor.';}state.nurseFilter='Completed';commit('Examination completed. The patient and doctor views are updated.');break;}
 case'reset-confirm':showModal('Start the demonstration again?',`<p>This restores the original fictional records, appointments and requests.</p>`,`<button class="btn" data-action="close">Keep my changes</button><button class="btn danger" data-action="reset">Reset demo</button>`);break;
 case'reset':state=prepareClinicalState(structuredClone(seed));expandedPassport=false;closeModal();commit('The demonstration has been reset.');break;
 case'explain':showModal('An addition to zVEM, not a replacement.',`<p>This local demonstration shows suggested improvements to the existing patient and doctor workflow.</p><ol class="plain-list"><li>The patient selects symptoms and pain locations, with optional details.</li><li>A request is organized by type, with the Patient Passport attached.</li><li>Automatic rules send the request to the nurse or doctor. Each professional records their own work.</li><li>The patient sees the result in the same request.</li></ol><div class="notice" style="margin-top:20px">${icon('shield')}<span>Only fictional records are used. The decision tree is illustrative, not clinically validated. No real healthcare service is connected.</span></div><p class="small muted" style="margin-top:20px">For a side-by-side demonstration, open this same file in three tabs: #patient, #doctor and #nurse. Saved changes are shared between these tabs where browser storage is available.</p>`,`<span></span><button class="btn primary" data-action="close">Got it</button>`);break;
 }
});
window.addEventListener('hashchange',()=>{closeModal();render();});
window.addEventListener('storage',event=>{if(event.key!==KEY||!event.newValue)return;try{const updated=JSON.parse(event.newValue);if(updated.version===2){state=prepareClinicalState(updated);render();}}catch{}});
document.addEventListener('input',event=>{if(flow&&event.target.id==='other-symptom')flow.answers.otherSymptom=event.target.value;});
document.addEventListener('keydown',event=>{if(event.target.matches('.body-region')&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(event.key==='Escape')closeModal();if(event.key==='Tab'&&modalRoot.children.length){const buttons=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],textarea,[tabindex="0"]')];const first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
render();
